import { useEffect, useState } from 'react';

/**
 * The floating "Track & Help" support widget.
 *
 * The original page drove this with a global `alxToggle()` and inline onclick
 * attributes; here it is plain React state. Markup, class names and behaviour
 * (including the Escape shortcut and the centred "support" variant) are
 * unchanged.
 *
 * Hand-written - not regenerated by tools/convert.mjs.
 */
export default function ContactWidget() {
  const [open, setOpen] = useState(false);
  const [centered, setCentered] = useState(false);
  const [mounted, setMounted] = useState(false);

  const toggle = (force) => {
    const next = force === undefined ? !open : force;
    setOpen(next);
    if (!next) setCentered(false);
  };

  useEffect(() => {
    setMounted(true);

    const onKeyDown = (e) => {
      if (e.key === 'Escape') {
        setOpen(false);
        setCentered(false);
      }
    };
    document.addEventListener('keydown', onKeyDown);

    // kept for parity with the original page, which exposed these globally
    window.alxToggle = (force) => {
      setOpen((prev) => {
        const next = force === undefined ? !prev : force;
        if (!next) setCentered(false);
        return next;
      });
    };
    window.alxSupportCenter = () => {
      setCentered(true);
      setOpen(true);
    };

    return () => {
      document.removeEventListener('keydown', onKeyDown);
      delete window.alxToggle;
      delete window.alxSupportCenter;
    };
  }, []);

  const cx = (...names) => names.filter(Boolean).join(' ');

  return (
    <>
      <div
        id="alx-overlay"
        className={cx(open && 'open', centered && 'dim')}
        onClick={() => toggle(false)}
      />

      <div id="alx-contact-container" className={cx(mounted && 'show')}>
        <div id="alx-dropdown" role="menu" className={cx(open && 'open', centered && 'alxw-center')}>
          <div className="alxw-head">
            <strong>WorldBridgeXpress Support</strong>
            <span>
              <span className="alxw-dot"></span>Online &mdash; we usually reply instantly
            </span>
          </div>

          <form className="alxw-track" method="GET" action="/track">
            <input type="text" name="code" placeholder="Enter a tracking number" autoComplete="off" required />
            <button type="submit">TRACK</button>
          </form>

          <a className="alxw-opt" href="tel:+19045676548" role="menuitem" onClick={() => toggle(false)}>
            <svg viewBox="0 0 24 24" fill="#11194E">
              <path d="M6.62 10.79c1.44 2.83 3.76 5.14 6.59 6.59l2.2-2.2c.27-.27.67-.36 1.02-.24 1.12.37 2.33.57 3.57.57.55 0 1 .45 1 1V20c0 .55-.45 1-1 1-9.39 0-17-7.61-17-17 0-.55.45-1 1-1h3.5c.55 0 1 .45 1 1 0 1.25.2 2.45.57 3.57.11.35.03.74-.25 1.02l-2.2 2.2z" />
            </svg>
            <div className="alxw-opt-t">
              <strong>Call Us</strong>
              <span>+1 (904) 567-6548</span>
            </div>
          </a>

          <a
            className="alxw-opt"
            href="https://wa.me/16722253278?text=Hello%20WorldBridgeXpress!"
            target="_blank"
            rel="noopener"
            role="menuitem"
            onClick={() => toggle(false)}
          >
            <svg viewBox="0 0 24 24" fill="#25D366">
              <path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893A11.821 11.821 0 0020.885 3.488" />
            </svg>
            <div className="alxw-opt-t">
              <strong>WhatsApp</strong>
              <span>+1 (672) 225-3278</span>
            </div>
          </a>

          <a className="alxw-opt" href="mailto:support@worldbridgexpress.com" role="menuitem" onClick={() => toggle(false)}>
            <svg viewBox="0 0 24 24" fill="#11194E">
              <path d="M20 4H4a2 2 0 00-2 2v12a2 2 0 002 2h16a2 2 0 002-2V6a2 2 0 00-2-2zm0 4l-8 5-8-5V6l8 5 8-5z" />
            </svg>
            <div className="alxw-opt-t">
              <strong>Email Us</strong>
              <span>We reply within a few hours</span>
            </div>
          </a>

          <div className="alxw-foot">WorldBridgeXpress &middot; Logistics Support</div>
        </div>

        {/* DTD CHAT BUTTON */}
        <div
          id="alx-contact-btn"
          onClick={() => toggle()}
          aria-haspopup="true"
          aria-expanded={open}
          aria-label="Contact WorldBridgeXpress"
          style={{ position: 'fixed', bottom: '24px', right: '18px', zIndex: 99998, cursor: 'pointer' }}
        >
          <div className="alxw-btn-core">
            <svg
              className="alxw-truck"
              viewBox="0 0 24 24"
              fill="none"
              stroke="white"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <path d="M5 17a2 2 0 1 0 4 0a2 2 0 1 0 -4 0" />
              <path d="M15 17a2 2 0 1 0 4 0a2 2 0 1 0 -4 0" />
              <path d="M5 17h-2v-4m-1 -8h11v12m-4 0h6m4 0h2v-6h-8m0 -5h5l3 5" />
              <path d="M3 9l4 0" />
            </svg>
            <div>
              <div className="alxw-btn-txt">TRACK &amp; HELP</div>
              <div className="alxw-btn-sub">
                <span className="alxw-dot"></span>Support online
              </div>
            </div>
          </div>
        </div>
      </div>
    </>
  );
}
